int lowerBound(int[] a, int x) {
    int lo = 0, hi = a.length;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (a[mid] < x) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;
}

void main() {
    int[] a = {1, 3, 3, 3, 8, 9};
    IO.println(lowerBound(a, 3) + " " + lowerBound(a, 4) + " " + lowerBound(a, 10));
